function InvoiceCorrection({record,sources,value,onChange}:{record:Item;sources:Item[];value:Item;onChange:(value:Item)=>void}) {
  const fields = value.fields || {};
  function setField(key:string,raw:string) {
    const next={...fields};
    if (!raw) delete next[key]; else next[key]=key === 'written_term_days' ? Number(raw) : raw;
    onChange({...value,fields:next});
  }
  return <details className="invoice-correction"><summary>Correct invoice facts</summary><p>Enter only the corrections supported by readable evidence. Saving changes rechecks the claim and invalidates any earlier approval.</p><label>Correction evidence<select value={value.source_id || ''} onChange={e => onChange({...value,source_id:e.target.value})}><option value="">Choose supporting document</option>{sources.filter(s => ['parsed','reviewed'].includes(s.status)).map(s => <option key={s.id} value={s.id}>{s.file}</option>)}</select></label><label>Correct invoice amount<input type="number" min="0.01" step="0.01" value={fields.amount || ''} placeholder={String(record.amount)} onChange={e => setField('amount',e.target.value)}/></label><label>Correct invoice date<input type="date" value={fields.date || ''} onChange={e => setField('date',e.target.value)}/></label><label>Correct acceptance date<input type="date" value={fields.acceptance_date || ''} onChange={e => setField('acceptance_date',e.target.value)}/></label><label>Correct written term (days)<input type="number" min="0" max="3650" value={fields.written_term_days ?? ''} placeholder={record.written_term_days == null ? 'No written term supplied' : String(record.written_term_days)} onChange={e => setField('written_term_days',e.target.value)}/></label><label>Reason for correcting this invoice<textarea rows={3} value={value.reason || ''} placeholder="Record the facts you checked in the supporting document" onChange={e => onChange({...value,reason:e.target.value})}/></label><p>Record your reviewer name below, then use Save review decisions.</p>{Object.keys(fields).length > 0 && <button className="text-button" onClick={() => onChange({})}>Discard corrections <X size={12}/></button>}</details>;
}

function SourceReferences({ source, sources, caseId, onOpen }: { source: Item; sources: Item[]; caseId?: string; onOpen: (ref: any) => void }) {
  const related = list(source.related_refs);
  const fields = Object.entries(source.field_sources || {}) as [string, string[]][];
  return <><div className="source-reference-list">{related.length > 1 && <><h4>All linked records</h4>{related.map((ref: any, idx) => { const id = typeof ref === 'string' ? ref : ref.source_id || ref.id; return <button key={idx} className="source-link" onClick={() => onOpen(ref)}><FileText size={13} /> {sources.find(s => s.id === id)?.file || id} <ArrowUpRight size={11} /></button>; })}</>}{fields.length > 0 && <><h4>Evidence by field</h4>{fields.map(([field, ids]) => <div className="field-source-row" key={field}><span>{field.replaceAll('_', ' ')}</span><div>{ids.map(id => <button key={id} className="source-link" onClick={() => onOpen(id)}>{sources.find(s => s.id === id)?.file || id} <ArrowUpRight size={10} /></button>)}</div></div>)}</>}</div>{source.stored_name && caseId && <a className="button secondary full-width source-download" href={`/api/cases/${caseId}/sources/${source.id}/download`} download><ArrowDownToLine size={15} /> Download original file</a>}</>;
}

function NewClaimModal({ onClose, onCreate, busy }: { onClose: () => void; onCreate: (profile: Item, files: File[]) => Promise<void>; busy: boolean }) {
  const [files, setFiles] = useState<File[]>([]);
  const [form, setForm] = useState({ name: '', category: 'micro', activity: 'manufacturing', udyam_number: '', udyam_date: '', address: '', buyer_name: '', buyer_address: '', as_of: new Date().toLocaleDateString('en-CA') });
  const upload = useRef<HTMLInputElement>(null);
  const update = (key: string, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  function submit(e: FormEvent) {
    e.preventDefault();
    onCreate({ supplier: { name: form.name, category: form.category, activity: form.activity, udyam_number: form.udyam_number, udyam_date: form.udyam_date, address: form.address }, buyer: { name: form.buyer_name, address: form.buyer_address }, as_of: form.as_of, invoices: [], payments: [], rates: [] }, files);
  }
  return <div className="modal-backdrop" onClick={() => !busy && onClose()}><section className="modal create-modal" role="dialog" aria-modal="true" aria-labelledby="claim-title" onClick={e => e.stopPropagation()}><div className="modal-heading"><div><h2 id="claim-title">Create a buyer claim</h2><p>One supplier, one buyer, and the records between them.</p></div><button className="icon-button" aria-label="Close create claim" disabled={busy} onClick={onClose}><X size={22} /></button></div><form onSubmit={submit}><div className="form-section-title">Your business</div><div className="form-grid"><label className="span-two">Legal business name<input required value={form.name} onChange={e => update('name', e.target.value)} placeholder="Name on your Udyam registration" /></label><label>Enterprise category<select value={form.category} onChange={e => update('category', e.target.value)}><option value="micro">Micro enterprise</option><option value="small">Small enterprise</option></select></label><label>Business activity<select value={form.activity} onChange={e => update('activity', e.target.value)}><option value="manufacturing">Manufacturing</option><option value="services">Services</option></select></label><label>Udyam registration number<input required value={form.udyam_number} onChange={e => update('udyam_number', e.target.value)} placeholder="UDYAM-XX-00-0000000" /></label><label>Udyam registration date<input required type="date" value={form.udyam_date} onChange={e => update('udyam_date', e.target.value)} /></label><label className="span-two">Business address<textarea required rows={2} value={form.address} onChange={e => update('address', e.target.value)} placeholder="Registered address, including state and PIN" /></label></div><div className="form-section-title">Your buyer</div><div className="form-grid"><label className="span-two">Buyer’s legal name<input required value={form.buyer_name} onChange={e => update('buyer_name', e.target.value)} placeholder="Name on the invoice / purchase order" /></label><label className="span-two">Buyer’s address<textarea required rows={2} value={form.buyer_address} onChange={e => update('buyer_address', e.target.value)} placeholder="Registered or correspondence address" /></label><label>Calculate interest through<input required type="date" value={form.as_of} onChange={e => update('as_of', e.target.value)} /></label></div><div className="form-section-title">Supporting records <span className="optional-label">Optional now</span></div><button type="button" className="modal-dropzone" onClick={() => upload.current?.click()}><UploadCloud size={25} /><strong>{files.length ? `${files.length} file${files.length > 1 ? 's' : ''} selected` : 'Add your supporting documents'}</strong><span>PDF, images, CSV, XLSX, or chat export</span></button><input hidden ref={upload} type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.csv,.xlsx,.txt,.webp,.tif,.tiff" onChange={e => setFiles(Array.from(e.target.files || []))} />{files.length > 0 && <div className="selected-files">{files.map((f, idx) => <span key={idx}><FileText size={13} />{f.name}<button type="button" aria-label={`Remove ${f.name}`} onClick={() => setFiles(prev => prev.filter((_, i) => idx !== i))}><X size={12} /></button></span>)}</div>}<div className="modal-footer"><span><ShieldCheck size={14} /> No automatic filing or sending</span><button className="button primary" type="submit" disabled={busy}>{busy ? <LoaderCircle className="spin" size={16} /> : <Plus size={16} />} Create claim</button></div></form></section></div>;
}
