  function activityTable(compact = false) {
    const rows = compact ? auditRows.slice(0, 4) : auditRows;
    return <section className="panel activity-panel"><div className="panel-heading"><div><h2>{compact ? 'Recent decisions' : 'Activity log'}</h2><p>Recorded actions and the reasons behind them.</p></div>{compact && <button className="text-button" onClick={() => goTo('audit')}>View full log <ArrowRight size={14}/></button>}</div>{rows.length ? <div className="table-wrap"><table className="activity-table"><thead><tr><th>Time</th><th>Action</th><th>Recorded detail</th></tr></thead><tbody>{rows.map((a, idx) => <tr key={idx}><td>{a.at ? new Date(a.at).toLocaleTimeString('en-IN', {hour:'2-digit',minute:'2-digit'}) : 'Not recorded'}<span className="table-sub">{date(a.at)}</span></td><td><strong>{String(a.action).replaceAll('_',' ')}</strong></td><td>{typeof a.detail === 'object' ? JSON.stringify(a.detail) : a.detail}</td></tr>)}</tbody></table></div> : <Empty title="No recorded actions yet" icon={History}>Create a claim to begin its audit trail.</Empty>}</section>;
  }

  function selectedRecordPanel() {
    const recordSources = list(selectedInvoice?.source_refs).map((ref: any) => sources.find(s => s.id === (typeof ref === 'string' ? ref : ref.source_id))).filter(Boolean);
    const recordMatches = list(claim?.matches).filter(m => m.invoice_id === selectedInvoice?.id);
    return <aside className="panel record-detail"><div className="panel-heading"><div><h2>{selectedInvoice?.number || 'Invoice detail'}</h2><p>{selectedInvoice ? 'Evidence and calculations for this invoice.' : 'Choose a record in the ledger.'}</p></div><FileText size={20}/></div>{selectedInvoice ? <div className="record-detail-body"><dl className="record-facts"><div><dt>Invoice amount</dt><dd>{rupees(selectedInvoice.amount)}</dd></div><div><dt>Principal outstanding</dt><dd>{rupees(selectedInvoice.outstanding)}</dd></div><div><dt>Calculated interest</dt><dd>{rupees(selectedInvoice.interest)}</dd></div><div><dt>Due date</dt><dd>{date(selectedInvoice.due_date)}</dd></div><div><dt>Acceptance / delivery</dt><dd>{date(selectedInvoice.acceptance_date || selectedInvoice.delivery_date)}</dd></div></dl><h3>Linked evidence</h3>{recordSources.map((s: any) => <button key={s.id} className="linked-document" onClick={() => openSource(s, selectedInvoice)}><FileText size={17}/><span><strong>{s.file}</strong><small>{sourceStatus(s.status)}{s.page ? ` · page ${s.page}` : s.line ? ` · line ${s.line}` : ''}</small></span><ArrowUpRight size={13}/></button>)}{!recordSources.length && <p className="muted">No source is linked to this record.</p>}<h3>Payment allocations</h3>{recordMatches.length ? recordMatches.map((m,idx) => <div className="allocation-detail" key={idx}><span><Banknote size={14}/>{m.payment_id}</span><strong>{rupees(m.amount)}</strong><p>{m.reason}{Number(m.tds_amount) > 0 ? ` · ${rupees(m.tds_amount)} evidenced TDS` : ''}</p>{refs(m)}</div>) : <p className="muted">No payment has been allocated to this invoice.</p>}<div className="detail-note"><ShieldCheck size={16}/><p>Due dates and interest follow the documented rules. Verify the source facts before approval.</p></div><button className="button primary full-width" onClick={() => goTo('review')}>Review claim packet <ArrowRight size={16}/></button></div> : <Empty title="Select an invoice">Its linked evidence will appear here.</Empty>}</aside>;
  }

  function evidenceWorkspace() {
    const sourceId = activeSource?.id;
    const recordFields = activeRecord ? Object.entries(activeRecord.field_sources || {}) as [string,string[]][] : [];
    const recordsForSource = [...invoices,...payments].filter(i => list(i.source_refs).includes(sourceId));
    const fileUrl = sourceId && claim ? `/api/cases/${claim.id}/sources/${sourceId}/download` : '';
    const isPdf = !!activeSource?.stored_name && /\.pdf$/i.test(activeSource.file || '');
    const isImage = !!activeSource?.stored_name && /\.(png|jpe?g|webp|tiff?)$/i.test(activeSource.file || '');
    const textLines = String(activeSource?.text || 'No extracted text is available. Open the original file or supply readable alternative evidence.').split('\n');
    return <section className="evidence-workspace" aria-label="Evidence review workspace">
      <aside className="panel evidence-browser"><div className="panel-heading"><div><h2>Documents <span className="count-pill">{sources.length}</span></h2><p>Original records in this claim.</p></div></div><div className="evidence-file-list">{sources.map(s => <button className={`evidence-file ${sourceId === s.id ? 'selected-file' : ''}`} key={s.id} onClick={() => openSource(s, [...invoices,...payments].find(r => list(r.source_refs).includes(s.id)))}><span className="file-thumbnail"><FileText size={23}/><span>{(s.file?.split('.').pop() || 'DOC').toUpperCase()}</span></span><span className="file-title"><strong>{s.file}</strong><small>{String(s.kind || 'Document').replaceAll('_',' ')}</small><Badge tone={needsReview(s.status) ? 'amber' : s.status === 'superseded' ? 'neutral' : 'green'}>{sourceStatus(s.status)}</Badge></span><ChevronRight size={13}/></button>)}</div><button className="button secondary add-evidence" disabled={!claim || !!busy} onClick={() => fileRef.current?.click()}><Plus size={15}/> Add documents</button></aside>
      <section className="panel evidence-document"><div className="panel-heading"><div><h2>{activeSource?.file || 'Source document'}</h2><p>{activeSource ? `${String(activeSource.kind || 'Evidence').replaceAll('_',' ')}${activeSource.page ? ` · page ${activeSource.page}` : ''}${activeSource.line ? ` · line ${activeSource.line}` : ''}` : 'Choose a document to inspect.'}</p></div>{activeSource && <Badge tone={needsReview(activeSource.status) ? 'amber' : activeSource.status === 'superseded' ? 'neutral' : 'green'}>{sourceStatus(activeSource.status)}</Badge>}</div><div className="document-toolbar"><span><FileText size={14}/>{isPdf || isImage ? 'Original file' : 'Extracted source text'}</span>{activeSource?.stored_name && <a className="text-button" href={fileUrl} download><ArrowDownToLine size={15}/> Download original</a>}</div><div className="document-stage">{activeSource ? isPdf ? <iframe title={`Original ${activeSource.file}`} src={fileUrl}/> : isImage ? <img className="original-image" src={fileUrl} alt={`Uploaded evidence: ${activeSource.file}`}/> : <article className="source-paper"><div className="source-paper-heading"><FileText size={25}/><div><strong>{activeSource.file}</strong><span>{synthetic ? 'Synthetic record · source text' : 'Uploaded record · extracted text'}</span></div></div><div className="document-lines">{textLines.map((line,idx) => <div className="document-line" key={idx}><span>{(activeSource.line || 1)+idx}</span><p>{line || '\u00a0'}</p></div>)}</div>{needsReview(activeSource.status) && <div className="document-status-note"><CircleAlert size={17}/><p>{sourceStatus(activeSource.status)}. This source needs review or readable replacement evidence before approval.</p></div>}</article> : <Empty title="No evidence to inspect">Create a claim and upload its records.</Empty>}</div>{activeSource?.sha256 && <details className="fingerprint"><summary><ShieldCheck size={14}/> Stored file fingerprint</summary><code>{activeSource.sha256}</code><p>Identifies uploaded bytes; it does not establish source authenticity.</p></details>}</section>
      <aside className="panel evidence-facts"><div className="panel-heading"><div><h2>Linked facts</h2><p>Read the document beside the values it supports.</p></div></div><div className="linked-facts-body">{activeRecord ? <><div className="fact-record-heading"><strong>{activeRecord.number || activeRecord.reference || activeRecord.id}</strong><Badge tone="neutral">{activeRecord.number ? 'Invoice' : 'Payment'}</Badge></div>{[{label:activeRecord.number ? 'Invoice amount' : 'Payment amount',value:rupees(activeRecord.amount),field:'amount'},{label:activeRecord.number ? 'Invoice date' : 'Payment date',value:date(activeRecord.date),field:'date'},...(activeRecord.number ? [{label:'Delivery / acceptance',value:date(activeRecord.acceptance_date || activeRecord.delivery_date),field:activeRecord.acceptance_date ? 'acceptance_date' : 'delivery_date'},{label:'Agreed written terms',value:activeRecord.written_term_days == null ? 'No written term supplied' : `${activeRecord.written_term_days} days`,field:'written_term_days'}] : [{label:'Payment reference',value:activeRecord.reference || 'No reference supplied',field:'reference'}])].map(f => <div className="linked-fact" key={f.label}><label>{f.label}</label><div className="fact-value">{f.value}</div><div className="fact-provenance">{list(activeRecord.field_sources?.[f.field]).length ? <><CheckCheck size={14}/><span>Source linked</span></> : <><CircleAlert size={14}/><span>No field source supplied</span></>}</div>{list(activeRecord.field_sources?.[f.field]).map((id:any,idx) => <button className="fact-source" key={idx} onClick={() => openSource(id,activeRecord)}><FileText size={14}/><span>{sources.find(s => s.id === id)?.file || id}</span><ArrowUpRight size={12}/></button>)}</div>)}{activeRecord.due_date && <div className="calculated-fact"><span>Calculated due date</span><strong>{date(activeRecord.due_date)}</strong><p>{claim?.rules?.due_date || 'Verify the acceptance date and agreed written terms.'}</p></div>}</> : <div className="facts-empty"><FileText size={25}/><h3>No typed fact links yet</h3><p>This record is still available as evidence. Add supported typed records or review the extraction before use.</p></div>}{recordsForSource.length > 1 && <div className="other-records"><h3>Other linked records</h3>{recordsForSource.filter(r => r.id !== activeRecord?.id).map(r => <button className="text-button" key={r.id} onClick={() => openSource(activeSource,r)}>{r.number || r.reference || r.id} <ArrowRight size={12}/></button>)}</div>}{recordFields.length > 0 && <details className="all-field-links"><summary>All field references ({recordFields.length})</summary><SourceReferences source={{...activeSource,field_sources:activeRecord?.field_sources,related_refs:activeRecord?.source_refs}} sources={sources} onOpen={ref => openSource(ref,activeRecord)}/></details>}{activeRecord?.number && <InvoiceCorrection record={activeRecord} sources={sources} value={invoiceEdits[activeRecord.id] || {}} onChange={value => setInvoiceEdits(prev => ({...prev,[activeRecord.id]:value}))}/>} {activeSource && needsReview(activeSource.status) && <div className="evidence-review-controls"><h3>Review this source</h3><label>Review note for {activeSource.file}<textarea rows={3} value={sourceReviews[sourceId]?.reason || ''} placeholder="Record what you checked against the original document" onChange={e => setSourceReviews(prev => ({...prev,[sourceId]:{reason:e.target.value,replacement:prev[sourceId]?.replacement || ''}}))}/></label>{['ocr_unavailable','parse_error'].includes(activeSource.status) && <label>Readable replacement<select aria-label="Readable replacement" value={sourceReviews[sourceId]?.replacement || ''} onChange={e => setSourceReviews(prev => ({...prev,[sourceId]:{reason:prev[sourceId]?.reason || '',replacement:e.target.value}}))}><option value="">Choose replacement evidence</option>{sources.filter(s => s.id !== sourceId && ['parsed','reviewed'].includes(s.status)).map(s => <option key={s.id} value={s.id}>{s.file}</option>)}